import {createHash} from 'node:crypto'
import {afterAll,beforeAll,describe,expect,it} from 'vitest'
import type {FastifyInstance} from 'fastify'
import type pg from 'pg'
import {AUTH_LOGIN_ROUTE,IDEMPOTENCY_KEY_HEADER,policyAiCandidateReviewResponseSchema,policyAiCandidatesResponseSchema,policyAiPromotionPreviewResponseSchema,policyAiPromotionResponseSchema,policyAiProvidersResponseSchema,policyAiRunResponseSchema,policyAiUsageResponseSchema,policyAnalysisResponseSchema} from '@hasarbotu/contracts'
import {POLICY_OCR_ENGINE_VERSION,POLICY_OCR_LANGUAGE_DATA_VERSION,POLICY_OCR_LOCATOR_VERSION,POLICY_OCR_NORMALIZATION_VERSION,POLICY_OCR_PREPROCESSING_VERSION,POLICY_OCR_QUALITY_VERSION,POLICY_OCR_RENDER_PROFILE_VERSIONS,policyOcrLanguageDataHash,type PolicyAiProviderId} from '@hasarbotu/domain'
